{"document_type": "report", "template": "operational-model", "data": "{
  "title": "Modelo de Ranqueamento de Candidatos — Matriz de Pontuação Composta",
  "version": "1.0",
  "date": "2025",
  "purpose": "Estabelecer critérios automáticos e transparentes de pontuação para ranquear candidatos em processos seletivos, considerando idade, origem socioespacial (CEP), instituição de formação e composição familiar.",
  "overview": {
    "escala_base": "0 a 100 pontos por fator, normalizados para comparabilidade",
    "nota_final": "média ponderada dos escores normalizados (0–100)",
    "ordenacao": "candidato com maior nota final recebe prioridade na sequência de entrevistas/chamada",
    "automatizacao": "aplicação automática a partir dos campos cadastrados, sem avaliação manual desses 4 critérios"
  },
  "factors": [
    {
      "name": "1. Idade (Peso: 20%)",
      "logic": "Desconto progressivo quanto maior a distância do público-alvo etário (até 35 anos = referência).",
      "table": [
        {"faixa": "Até 25 anos", "score": 100},
        {"faixa": "26–35 anos", "score": 80},
        {"faixa": "36–45 anos", "score": 60},
        {"faixa": "46–55 anos", "score": 40},
        {"faixa": "Acima de 55 anos", "score": 20}
      ],
      "formula": "score_idade = 100 − ((anos_acima_de_35 × 10))",
      "example": "Candidato de 42 anos → 100 − (7 × 10) = 30"
    },
    {
      "name": "2. Origem Socioespacial – CEP (Peso: 30%)",
